update private.pilot_settings set catalog_version='synthetic-pakistan-catalog-v5' where id=true;
insert into private.studies(id,protocol_version,catalog_version,layout_version,base_config,catalog_snapshot)
select 'almab-factorial-test-v3','candidate-protocol-v3','synthetic-pakistan-catalog-v5','physical-rack-v4',
'{"schemaVersion":2,"budget":600,"markupPercent":25,"placementRule":"upf-or-high","controlLayout":"targets-eye"}',jsonb_agg(product order by (product->>'catalogOrder')::integer)
from private.catalog where version='synthetic-pakistan-catalog-v5';
create or replace function public.get_or_start_study_task(p_study_id text) returns jsonb
language plpgsql security definer set search_path='' as $$
declare p public.participant_profiles; s private.studies; a private.allocations; v_task uuid; n integer; c integer; cfg jsonb;
begin
 select * into p from public.participant_profiles where user_id=auth.uid();
 if p.user_id is null or p.height_cm is null or p.weight_kg is null or p.waist_cm is null then raise exception 'profile_incomplete'; end if;
 -- One study-row lock serializes allocation, including two devices starting together.
 select * into s from private.studies where id=p_study_id for update;
 if not found then raise exception 'study_unavailable'; end if;
 select * into a from private.allocations where study_id=s.id and participant_id=p.participant_id;
 if a.id is not null then
  select id into strict v_task from private.study_tasks where allocation_id=a.id;
  return private.study_task_json(v_task);
 end if;
 if not s.enrollment_open or not s.tasks_open then raise exception 'study_closed'; end if;
 if p.consent_version is distinct from s.consent_version or s.consent_version='' then raise exception 'study_consent_mismatch'; end if;
 if p.catalog_version is distinct from s.catalog_version then raise exception 'catalog_version_mismatch'; end if;
 if s.base_config->>'controlLayout' not in ('targets-eye','category','popularity')
 or (s.base_config->>'budget')::integer not between 100 and 5000
 or (s.base_config->>'markupPercent')::integer not in (20,25,30)
 or s.base_config->>'placementRule' not in ('upf','upf-or-high')
 or jsonb_array_length(s.catalog_snapshot)<>(case when s.catalog_version='synthetic-pakistan-catalog-v5' then 75 else 50 end) then raise exception 'invalid_study_definition'; end if;
 select coalesce(max(ordinal),0)+1 into n from private.allocations where study_id=s.id;
 if not exists(select 1 from private.randomization_slots where study_id=s.id and ordinal=n) then
  insert into private.randomization_slots(study_id,ordinal,condition)
  select s.id,n-1+row_number() over(order by gen_random_uuid()),k%8 from generate_series(0,15) k;
 end if;
 select condition into strict c from private.randomization_slots where study_id=s.id and ordinal=n;
 cfg:=(s.base_config-'controlLayout')||jsonb_build_object('price',(c&4)<>0,'position',(c&2)<>0,
  'layoutMode',case when (c&2)<>0 then 'alternatives-eye' else s.base_config->>'controlLayout' end,
  'labels',(c&1)<>0,'upf',(c&1)<>0);
 insert into private.allocations(study_id,participant_id,ordinal,condition,config) values(s.id,p.participant_id,n,c,cfg) returning * into a;
 insert into private.study_tasks(allocation_id) values(a.id) returning id into v_task;
 return private.study_task_json(v_task);
end; $$;

-- All outcome calculations use the immutable study catalog, not browser values.

create or replace function private.study_basket_result(p_basket jsonb,p_config jsonb,p_catalog jsonb) returns jsonb
language plpgsql set search_path='' as $$
declare item jsonb; product jsonb; qty integer; unit_price bigint; amount bigint:=0; energy numeric:=0;
 upf_energy numeric:=0; unknown_energy numeric:=0; item_energy numeric; ids text[]:='{}'; items jsonb:='[]'; count_units integer:=0;
begin
 if p_basket is null or jsonb_typeof(p_basket)<>'array' or jsonb_array_length(p_basket)>jsonb_array_length(p_catalog) then raise exception 'invalid_basket'; end if;
 for item in select value from jsonb_array_elements(p_basket) loop
  if jsonb_typeof(item)<>'object' or jsonb_typeof(item->'id') is distinct from 'string'
   or jsonb_typeof(item->'quantity') is distinct from 'number' or (item->>'quantity') !~ '^[1-9][0-9]?$'
   or (select count(*) from jsonb_object_keys(item))<>2 then raise exception 'invalid_item'; end if;
  if item->>'id'=any(ids) then raise exception 'duplicate_item'; end if;
  ids:=array_append(ids,item->>'id'); qty:=(item->>'quantity')::int;
  select value into product from jsonb_array_elements(p_catalog) where value->>'id'=item->>'id';
  if product is null then raise exception 'unknown_product'; end if;
  unit_price:=private.product_price_minor(product,p_config); amount:=amount+unit_price*qty; count_units:=count_units+qty;
  item_energy:=(product->>'kcal')::numeric*(product->>'size')::numeric/100*qty; energy:=energy+item_energy;
  if product->>'nova'='4' then upf_energy:=upf_energy+item_energy; end if;
  if product->>'nova' is null then unknown_energy:=unknown_energy+item_energy; end if;
  items:=items||jsonb_build_array(jsonb_build_object('product_id',product->>'id','quantity',qty,
   'base_price_pkr',(product->>'price')::numeric,'unit_price_pkr',unit_price/100.0,'line_total_pkr',unit_price*qty/100.0,
   'sale_unit',coalesce(product->>'saleUnit','pack_or_portion'),'pieces_per_unit',case when product->>'saleUnit'='piece' then (product->>'portionCount')::integer else null end,'size',(product->>'size')::numeric,'unit',product->>'unit','nova',product->'nova','energy_kcal',item_energy,
   'fat_g',(product->>'fat')::numeric*(product->>'size')::numeric/100*qty,
   'sugars_g',(product->>'sugar')::numeric*(product->>'size')::numeric/100*qty,
   'salt_g',(product->>'salt')::numeric*(product->>'size')::numeric/100*qty));
 end loop;
 if amount>(p_config->>'budget')::bigint*100 then raise exception 'budget_exceeded'; end if;
 return jsonb_build_object('amountMinor',amount,'energy',energy,'upfEnergy',upf_energy,'unknownEnergy',unknown_energy,
 'upfShare',case when energy>0 and unknown_energy=0 then upf_energy/energy else null end,'count',count_units,'items',items);
end; $$;



create or replace function public.submit_pilot_task(p_session_id uuid,p_basket jsonb,p_language text,p_catalog_version text)
returns jsonb language plpgsql security definer set search_path='' as $$
declare
 p public.participant_profiles; s private.pilot_settings; existing private.pilot_tasks; row record;
 item jsonb; product jsonb; qty int; price_minor bigint; amount_minor bigint:=0;
 energy numeric:=0; upf_energy numeric:=0; unknown_energy numeric:=0; item_energy numeric;
 ids text[]:='{}'; result jsonb; submitted timestamptz;
begin
 select * into p from public.participant_profiles where user_id=auth.uid();
 if not found then raise exception 'profile_required'; end if;
 if p_session_id is null or p_basket is null or jsonb_typeof(p_basket)<>'array' or jsonb_array_length(p_basket)>100 then raise exception 'invalid_basket'; end if;
 if p_language is null or p_language not in ('zh','en','ur') or p_catalog_version is distinct from p.catalog_version then raise exception 'invalid_task_metadata'; end if;
 -- Serialize a retry for the same UUID; completed submissions are immutable.
 perform pg_advisory_xact_lock(hashtextextended(p_session_id::text,0));
 select * into existing from private.pilot_tasks where session_id=p_session_id;
 if found then
  if existing.participant_id<>p.participant_id or existing.basket<>p_basket then raise exception 'session_conflict'; end if;
  return jsonb_build_object('session_id',existing.session_id,'submitted_at',existing.submitted_at,'result',existing.result);
 end if;
 select * into strict s from private.pilot_settings where id=true;
 if not s.enrollment_open then raise exception 'enrollment_closed'; end if;
 for item in select value from jsonb_array_elements(p_basket) loop
  if jsonb_typeof(item)<>'object' or jsonb_typeof(item->'id') is distinct from 'string' or jsonb_typeof(item->'quantity') is distinct from 'number'
    or (select count(*) from jsonb_object_keys(item))<>2 or (item->>'quantity') !~ '^[1-9][0-9]?$' then raise exception 'invalid_item'; end if;
  qty:=(item->>'quantity')::int;
  if item->>'id'=any(ids) then raise exception 'duplicate_item'; end if;
  ids:=array_append(ids,item->>'id');
  select c.product into product from private.catalog c where c.id=item->>'id' and c.version=p.catalog_version;
  if not found then raise exception 'unknown_product'; end if;
  price_minor:=private.product_price_minor(product,p.pilot_config);
  amount_minor:=amount_minor+price_minor*qty;
  item_energy:=(product->>'kcal')::numeric*(product->>'size')::numeric/100*qty;
  energy:=energy+item_energy;
  if (product->>'nova')::int=4 then upf_energy:=upf_energy+item_energy; end if;
  if product->>'nova' is null then unknown_energy:=unknown_energy+item_energy; end if;
 end loop;
 if amount_minor>(p.pilot_config->>'budget')::bigint*100 then raise exception 'budget_exceeded'; end if;
 result:=jsonb_build_object('amountMinor',amount_minor,'energy',energy,'upfEnergy',upf_energy,'unknownEnergy',unknown_energy,
  'upfShare',case when energy>0 and unknown_energy=0 then upf_energy/energy else null end,'config',p.pilot_config,'syntheticProducts',true,'assignment','fixed-pilot-not-randomized','layoutVersion',case when p.pilot_config->>'schemaVersion'='2' then case when p.catalog_version='synthetic-pakistan-catalog-v5' then 'physical-rack-v4' when p.catalog_version='synthetic-pakistan-catalog-v4' then 'physical-rack-v3' when p.catalog_version='synthetic-pakistan-catalog-v3' then 'physical-rack-v2' else 'physical-rack-v1' end else 'legacy' end,'facingsPerSku',case when p.pilot_config->>'schemaVersion'='2' then 2 else null end);
 insert into private.pilot_tasks(session_id,participant_id,basket,language,catalog_version,result)
 values(p_session_id,p.participant_id,p_basket,p_language,p_catalog_version,result) returning submitted_at into submitted;
 return jsonb_build_object('session_id',p_session_id,'submitted_at',submitted,'result',result);
end;
$$;


notify pgrst, 'reload schema';

notify pgrst, 'reload schema';
commit;
